ALTER TABLE "global_overhead_periods" DROP CONSTRAINT "overhead_period_valid";--> statement-breakpoint
ALTER TABLE "global_overhead_periods" ADD CONSTRAINT "overhead_period_valid" CHECK (extract(day from "global_overhead_periods"."period_month") = 1 AND "global_overhead_periods"."forecast_units_remaining" > 0 AND "global_overhead_periods"."opening_carry_forward_rupiah" >= 0 AND (("global_overhead_periods"."status" = 'OPEN' AND "global_overhead_periods"."closed_at" IS NULL AND "global_overhead_periods"."closing_unrecovered_rupiah" IS NULL) OR ("global_overhead_periods"."status" = 'CLOSED' AND "global_overhead_periods"."closed_at" IS NOT NULL AND "global_overhead_periods"."closing_unrecovered_rupiah" IS NOT NULL AND "global_overhead_periods"."closing_unrecovered_rupiah" >= 0)));